from threetears.evals import Eval

from messages import render

def show(case):
    """The string the app shows for the template and its values."""
    return {"text": render(case["template"], case["values"])}


def as_approved(case, out):
    """The string is the approved text."""
    return out["text"] == case["approved"]

strings = Eval("data/strings.jsonl", runner=show, grader=[as_approved], k=1)
